def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    # Iterate from topmost (last) to bottom
    for idx in range(n - 1, -1, -1):
        a, b, g, k = carpets[idx]
        if a <= x <= a + g and b <= y <= b + k:
            return idx + 1  # 1-based index
    return -1

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0:
            break
        grid[x][y] = val

    if N == 1:
        return grid[1][1]

    # dp[x1][x2] = max sum when both walkers have taken t steps and are at (x1, y1) and (x2, y2)
    # y1 = t + 2 - x1, y2 = t + 2 - x2
    INF_NEG = -10**9
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    total_steps = 2 * N - 2  # number of moves from (1,1) to (N,N)
    for t in range(1, total_steps + 1):
        dp_next = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        for x1 in range(1, N + 1):
            y1 = t + 2 - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(1, N + 1):
                y2 = t + 2 - x2
                if y2 < 1 or y2 > N:
                    continue
                best_prev = INF_NEG
                # four possible previous moves
                for dx1 in (0, 1):  # 0: came from left (x1-1), 1: came from up (x1)
                    for dx2 in (0, 1):
                        prev_x1 = x1 - dx1
                        prev_x2 = x2 - dx2
                        if prev_x1 < 1 or prev_x2 < 1:
                            continue
                        prev_y1 = (t - 1) + 2 - prev_x1
                        prev_y2 = (t - 1) + 2 - prev_x2
                        if prev_y1 < 1 or prev_y1 > N or prev_y2 < 1 or prev_y2 > N:
                            continue
                        val = dp[prev_x1][prev_x2]
                        if val > best_prev:
                            best_prev = val
                if best_prev == INF_NEG:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                dp_next[x1][x2] = best_prev + add
        dp = dp_next

    return dp[N][N]

def find_number_combinations():
    def is_valid(num):
        s = str(num)
        if len(s) != 3:
            return False
        digits = [int(ch) for ch in s]
        if any(d == 0 for d in digits):
            return False
        if len(set(digits)) != 3:
            return False
        return True

    combinations = []
    for n in range(100, 334):  # 3*n <= 999
        if not is_valid(n):
            continue
        m = 2 * n
        p = 3 * n
        if m > 999 or p > 999:
            continue
        if is_valid(m) and is_valid(p):
            combinations.append((n, m, p))
    return combinations

def cantor_numbering(N: int) -> str:
    # Find the diagonal k such that k*(k+1)//2 >= N
    low, high = 1, 2 * N  # upper bound
    while low < high:
        mid = (low + high) // 2
        if mid * (mid + 1) // 2 >= N:
            high = mid
        else:
            low = mid + 1
    k = low
    # Number of terms before this diagonal
    prev_terms = (k - 1) * k // 2
    pos = N - prev_terms  # 1-indexed position within diagonal
    if k % 2 == 0:
        numerator = pos
        denominator = k - pos + 1
    else:
        numerator = k - pos + 1
        denominator = pos
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    # Ensure the provided length matches the string length
    if N != len(num_str):
        N = len(num_str)
    # dp[i][k] = maximum product for prefix of length i with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    # Iterate over end position i
    for i in range(1, N + 1):
        val = 0
        pow10 = 1
        # Build all substrings ending at i in reverse order
        for j in range(i - 1, -1, -1):
            val = int(num_str[j]) * pow10 + val
            pow10 *= 10
            # Base case: no multiplication signs
            if j == 0:
                dp[i][0] = val
            else:
                # Try adding a multiplication sign before position j
                for k in range(1, K + 1):
                    if j >= k:  # enough digits to place k-1 signs before j
                        candidate = dp[j][k - 1] * val
                        if candidate > dp[i][k]:
                            dp[i][k] = candidate
    return dp[N][K]

