def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        sign = ''
        if not terms:
            if coeff < 0:
                sign = '-'
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''
        terms.append(f'{sign}{coeff_str}{var_part}')
    return ''.join(terms) if terms else '0'

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    enc_to_orig = {}
    orig_to_enc = {}
    for e, o in zip(encoded, original):
        if e in enc_to_orig:
            if enc_to_orig[e] != o:
                return "Failed"
        else:
            enc_to_orig[e] = o
        if o in orig_to_enc:
            if orig_to_enc[o] != e:
                return "Failed"
        else:
            orig_to_enc[o] = e
    if len(enc_to_orig) != 26 or len(orig_to_enc) != 26:
        return "Failed"
    decoded_chars = []
    for ch in message:
        if ch not in enc_to_orig:
            return "Failed"
        decoded_chars.append(enc_to_orig[ch])
    return "".join(decoded_chars)

def largest_prime_factor(n: int) -> int:
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if k == 0:
        return 1 if n == 0 else 0
    m = n - k * x
    if m < 0:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for part in range(1, k + 1):
        for i in range(part, m + 1):
            dp[i] += dp[i - part]
    return dp[m]

def count_coprime_pairs(x0: int, y0: int) -> int:
    # Helper function to compute gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0
    n = y0 // x0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

