def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps.
    """
    if A == B:
        return 0

    visited = {A}
    queue = [(A, 0)]

    while queue:
        current, steps = queue.pop(0)

        if steps >= 10:
            continue  # cannot go beyond 10 steps

        for src, tgt in rules:
            src_len = len(src)
            if src_len == 0:
                continue  # avoid infinite loop on empty source
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + src_len:]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    s = str(n)
    # Build mapping from digit to possible replacements
    mapping = {}
    for x, y in rules:
        mapping.setdefault(str(x), set()).add(str(y))
    # BFS
    from collections import deque
    visited = {s}
    queue = deque([s])
    while queue:
        cur = queue.popleft()
        for i, d in enumerate(cur):
            if d in mapping:
                for rep in mapping[d]:
                    new_num = cur[:i] + rep + cur[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for speaker, stmts in statements.items():
        for stmt in stmts:
            # Remove trailing period and split into words
            words = stmt.replace('.', '').split()
            if not words:
                continue
            # Skip statements that mention a day of the week
            if any(day.lower() in (w.lower() for w in words) for day in days_of_week):
                continue
            # Determine truth value of the statement
            truth = None
            if words[0] == "I":
                if len(words) >= 3 and words[1] == "am":
                    if words[2] == "guilty":
                        truth = (scenario == speaker)
                    elif words[2] == "not" and len(words) >= 4 and words[3] == "guilty":
                        truth = (scenario != speaker)
            else:
                name = words[0]
                if len(words) >= 3 and words[1] == "is":
                    if words[2] == "guilty":
                        truth = (scenario == name)
                    elif words[2] == "not" and len(words) >= 4 and words[3] == "guilty":
                        truth = (scenario != name)
            # If the statement format is unrecognized, skip it
            if truth is None:
                continue
            # Check consistency with liar status
            if speaker in liar_count:
                if truth:  # liars cannot tell the truth
                    return False
            else:
                if not truth:  # non-liars cannot lie
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    scores = []
    p_score = 0
    o_score = 0
    for ch in points:
        if ch == 'W':
            p_score += 1
        elif ch == 'L':
            o_score += 1
        else:
            # ignore any other characters
            continue
        if (p_score >= system or o_score >= system) and abs(p_score - o_score) >= 2:
            scores.append(f"{p_score}:{o_score}")
            p_score = 0
            o_score = 0
    if p_score > 0 or o_score > 0:
        scores.append(f"{p_score}:{o_score}")
    return scores

