def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize DP array where dp[t] is the maximum value achievable with time t
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        # Traverse backwards to avoid using the same herb multiple times
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val
    return dp[T] if T >= 0 else 0

def mod_inverse(a, b):
    """
    Calculate the modular multiplicative inverse of a modulo b.
    Returns an integer x such that (a * x) % b == 1 if it exists,
    otherwise returns None.
    """
    if b == 0:
        return None

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None
    return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappy = 0
    best_day = 0
    for i, (school, extra) in enumerate(schedule, start=1):
        total = school + extra
        if total > 8:
            unhappy = total - 8
            if unhappy > max_unhappy:
                max_unhappy = unhappy
                best_day = i
    return best_day if max_unhappy > 0 else 0

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    max_len = 0
    for i in range(n):
        cur = inc[i] + dec[i] - 1
        if cur > max_len:
            max_len = cur
    return n - max_len
